import sys
from collections import Counter
from math import isqrt

def count_suitable_pairs(n, k, a):
    count = 0
    freq = Counter()

    for num in a:
        if num == 0:
            continue
        # Check for each divisor if it can be a base of x^k
        for d in range(1, isqrt(num) + 1):
            if num % d == 0:
                # Check both divisors d and num // d
                if pow(d, k) == num:
                    count += freq[d]
                if pow(num // d, k) == num and d != num // d:
                    count += freq[num // d]
        freq[num] += 1

    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    result = count_suitable_pairs(n, k, a)
    print(result)

if __name__ == "__main__":
    main()
